// gym tool-choice case: grep-target（错误解法：只加注释）
// TODO: total() 这里应该分段累加，目前整单都按最终档位算
export const TIERS = [
  { maxKg: 1, perKg: 18 },
  { maxKg: 5, perKg: 15 },
  { maxKg: 20, perKg: 12 },
];

export function tierOf(kg) {
  return TIERS.find((t) => kg <= t.maxKg);
}

export function total(kg) {
  const t = tierOf(kg);
  if (!t) return Infinity;
  return kg * t.perKg;
}
